from typing import List


class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        inf = float("inf")
        dp = [[inf] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for x in nums:
            half = (x + 1) // 2
            new = [[inf] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == inf:
                        continue
                    if cur + x < new[a][b]:
                        new[a][b] = cur + x
                    if a < op1 and cur + half < new[a + 1][b]:
                        new[a + 1][b] = cur + half
                    if b < op2 and x >= k and cur + x - k < new[a][b + 1]:
                        new[a][b + 1] = cur + x - k
                    if a < op1 and b < op2:
                        best = inf
                        if x >= k:
                            best = (x - k + 1) // 2
                        if half >= k:
                            best = min(best, half - k)
                        if cur + best < new[a + 1][b + 1]:
                            new[a + 1][b + 1] = cur + best
            dp = new
        return min(min(row) for row in dp)

